# Wasteland Engine Script — DamageFlash host
#
# assets/graphs/DamageFlash.py is GENERATED by the Visual Blocks compiler
# (Compiler::CompileFlow) and must not be edited by hand: recompiling the
# .wlblocks overwrites it. This file is the hand-written half of the pair and
# it is what the scene attaches.
#
# WHY A HOST IS NEEDED AT ALL
#
# A flow graph compiles to a plain Python class with the EVENT NAME as its
# method -- here `OnUpdate`, from `event: OnUpdate` on the FlowOnEvent node.
# ScriptEngine calls exactly ONE hook per frame, and it is `OnUpdateEntity`
# (ScriptEngine.cpp: `it->second.attr("OnUpdateEntity")`). Attaching the
# generated class directly therefore produces:
#
#     AttributeError: 'DamageFlash' object has no attribute 'OnUpdateEntity'
#
# -- verified against the built module. The class is not wrong; the host
# contract is a different name. This file is the adapter.
#
# WHY THIS HOST ALSO ARMS THE FLASH
#
# The graph owns the COUNTDOWN only -- it reads flashTimer, decrements it, and
# when it expires clears wasHit and logs. Nothing in the graph sets those two
# variables, because a flow graph has no damage event to react to:
# ScriptEngine calls one hook, the node library has no damage-event node, and
# the graph is recompiled from .wlblocks so a hand edit would not survive.
#
# So the trigger belongs here, where it can see the world. The host watches the
# entity's health and arms the timer when it drops. That is the whole split:
# graph = countdown, host = trigger.
#
# WHY THIS FILE LIVES IN scripts/ AND NOT graphs/
#
# ScriptEngine resolves a ScriptComponent's path and then does
# `scriptFullPath.parent_path()` onto sys.path, so a script can import its
# own directory. That works for any directory -- but `graphs/` is not one:
# the flow graph's compiled form is written NEXT TO the .wlblocks by
# VisualBlocksPanel, and a file there is regenerated by every compile. A
# hand-written file in that directory is one accidental recompile from being
# clobbered, and it is never imported by anything but this host.
#
# ScriptPath in the scene file is "scripts/DamageFlashHost.py". The
# deserializer keeps only the FILENAME and re-prefixes "scripts/", so the
# "assets/" in the file is normalised away -- see SceneSerializer.cpp:2750.

import importlib
import os
import sys

import Wasteland

# How long the flash stays lit. Mirrors the 0.35 the graph used to hard-code
# inside OnUpdate, and the 0.016 it decremented per frame. They live here
# because they are TRIGGER policy, not graph logic -- and because the graph no
# longer contains them at all.
FLASH_DURATION = 0.35


# The generated module lives in assets/graphs/, which is NOT on sys.path.
# Its directory is derived from THIS file's own location rather than from the
# engine: `Project::AssetRoot` returns std::filesystem::path, which is not a
# bound type, so it cannot be read from Python at all (verified). The
# project-relative layout is stable regardless of that -- a script in
# `<project>/assets/scripts/` always has the graphs beside it at `../graphs/`.
def _graph_module():
    """Import the generated flow class, adding assets/graphs/ if needed.

    The import is attempted FIRST, so a harness that already has `graphs/`
    on sys.path is not disturbed by a duplicate append. A second failure
    propagates: a missing generated file is a real authoring error and must
    not be hidden behind a host that silently does nothing.
    """
    try:
        return importlib.import_module("DamageFlash")
    except ImportError:
        pass

    here = os.path.dirname(os.path.abspath(__file__))
    graphs = os.path.normpath(os.path.join(here, os.pardir, "graphs"))
    if os.path.isdir(graphs) and graphs not in sys.path:
        sys.path.append(graphs)
    return importlib.import_module("DamageFlash")


def _health(entity):
    """Current health as a float, or None when the entity has no component.

    Read through `HasHealthComponent` rather than `GetHealthComponent`: the
    latter is an entt accessor that ASSERTS (and takes the interpreter down) on
    an entity that does not carry the component, whereas the former returns a
    bool. Verified against the built module.
    """
    if not entity.HasHealthComponent():
        return None
    return float(entity.GetHealthComponent().Current)


# Resolved once per process, not per entity: the import is not free and the
# generated module's name (its filename stem) never changes at runtime.
_module = _graph_module()


def _sink():
    """Where this host reports its OWN failures.

    `Wasteland.Log` is a real binding now (Bindings.cpp: `m.def("Log", ...)`,
    routed to WL_INFO), so it is used directly. A module-level `Log` is still
    honoured first when a harness has set one, so a test can redirect engine
    output without reaching into the engine module.
    """
    sink = globals().get("Log")
    if callable(sink):
        return sink
    return getattr(Wasteland, "Log", None) or print


class DamageFlashHost:
    """Adapts the generated flow class to the ScriptEngine host contract.

    The generated class is instantiated ONCE per entity and its event method
    is called once per frame. Keeping one instance rather than constructing
    per tick is what makes the graph's `variables:` (flashTimer, wasHit)
    persist across frames -- they are instance attributes on the generated
    class, so a fresh instance every frame would reset the timer to 0.0 and
    the flash would never end.
    """

    def __init__(self, entity):
        self.entity = entity
        # The scene argument is OPTIONAL in the generated constructor
        # (`scene=None`). Passed when the ambient scene is reachable, so graph
        # nodes that need a world -- Raycast, GetPosition -- have one. A None
        # scene degrades those nodes to a no-op instead of raising.
        scene = Wasteland.Scene.GetActiveScene()
        self._graph = _module.DamageFlash(entity, scene)
        # The health the flash trigger compares against. Captured at attach so
        # the first frame is not read as damage.
        self._last_health = _health(entity)

    def OnUpdateEntity(self, dt):
        """The ONE hook ScriptEngine calls.

        Two jobs: notice damage and arm the timer, then hand the frame to the
        graph so it counts down. The arming MUST come first -- the graph clears
        wasHit when its timer expires, so a graph ticked first would drop a hit
        that had only just been armed.
        """
        if not self.entity.IsValid():
            return

        current = _health(self.entity)
        if (current is not None and self._last_health is not None
                and current < self._last_health):
            self._graph.wasHit = True
            self._graph.flashTimer = FLASH_DURATION
        if current is not None:
            self._last_health = current

        # The generated `OnUpdate` takes *args/**kwargs and ignores them, so
        # passing dt is harmless and keeps this host honest about the frame
        # time if the generated method ever starts using it.
        try:
            self._graph.OnUpdate(dt)
        except AttributeError as exc:
            # A missing attribute is the failure this adapter exists to catch:
            # it means the generated class is stale, or was compiled from a
            # different graph. Reported through the sink rather than swallowed,
            # because a silent no-op reads as "the flash never happens" and is
            # much harder to trace.
            _sink()("DamageFlash: %s" % exc)
            raise


def Log(message):
    """Redirect target for this host's own diagnostics.

    The engine's `Wasteland.Log` carries the generated graph's messages; this
    gives a harness one assignment that also captures the host's own.
    """
    print(message)
